mapper.update:
UPDATE wiki_asset
SET content = #{content}, update_by = 'system', update_time = NOW()
WHERE asset_type = #{assetType} AND asset_name = #{slug} AND status = #{status}

UPDATE wiki_asset
SET status = #{inactiveStatus}, update_by = 'system', update_time = NOW()
WHERE asset_type = #{assetType} AND asset_name = #{slug}

mapper.select:
SELECT content FROM wiki_asset
WHERE asset_type = #{assetType} AND tags = #{tag} AND status = #{status}
LIMIT 1

SELECT asset_name, domain_name, description, update_time
FROM wiki_asset
WHERE asset_type = #{assetType} AND status = #{status} AND COALESCE(tags, '') <> #{tag}
ORDER BY asset_name
LIMIT #{limit}

SELECT asset_id FROM wiki_asset
WHERE asset_type = #{assetType} AND tags = #{tag}
LIMIT 1

mapper.update:
UPDATE wiki_asset
SET content = #{content}, update_by = 'system', update_time = NOW()
WHERE asset_id = #{assetId}

mapper.select:
SELECT asset_id, space_id, asset_name, asset_type, domain_name, description, content
FROM wiki_asset
WHERE asset_id = #{assetId} AND status = #{status}

SELECT asset_id, asset_name, asset_type, domain_name, description
FROM wiki_asset
WHERE status = #{status}


        AND asset_type <> #{pageType}


        AND asset_type NOT IN (#{pageType}, 'URL')


  AND content IS NOT NULL AND CHAR_LENGTH(TRIM(content)) > 0


        AND (asset_id = #{scopeId} OR tags = #{sourceTag})


        AND space_id = #{spaceId}


ORDER BY update_time DESC, asset_id DESC
LIMIT #{limit}

SELECT asset_id, asset_name, asset_type, domain_name, description
FROM wiki_asset
WHERE status = #{status}
  AND asset_type = #{assetType}
  AND COALESCE(tags, '') <> #{indexTag}
  AND content IS NOT NULL AND CHAR_LENGTH(TRIM(content)) > 0


        AND (asset_id = #{scopeId} OR tags = #{sourceTag})


        AND space_id = #{spaceId}


ORDER BY update_time DESC, asset_id DESC
LIMIT #{limit}

SELECT asset_id, space_id, asset_name, asset_type, tags,
       CASE WHEN asset_type = 'WIKI_PAGE' THEN SUBSTRING(content, 1, #{contentLen}) ELSE NULL END content
FROM wiki_asset
WHERE status = #{status} AND COALESCE(tags, '') <> #{indexTag}

    AND space_id = #{spaceId}

ORDER BY asset_name
LIMIT #{limit}

SELECT a.asset_id, m.source_json
FROM wiki_asset a
JOIN ontology_analysis_memory m
  ON a.tags = CONCAT('ANALYSIS_MEMORY:', m.memory_id)
WHERE a.status = #{status} AND a.asset_type = #{pageType}

    AND a.space_id = #{spaceId}

SELECT asset_id sourceId, asset_name title, content
FROM wiki_asset
WHERE status = #{status} AND space_id = #{spaceId}
  AND content IS NOT NULL AND CHAR_LENGTH(TRIM(content)) > 0
  AND UPPER(asset_type) IN

    #{type}

ORDER BY update_time DESC, asset_id DESC
LIMIT #{limit}
